import{_ as a,o as n,c as e,a6 as t}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"HTTP/2 与 HTTP/3","description":"http2 指令取代 listen 参数、QUIC 的双 listen 与 Alt-Svc、quic_gso 与 0-RTT 的前置条件。","frontmatter":{"title":"HTTP/2 与 HTTP/3","description":"http2 指令取代 listen 参数、QUIC 的双 listen 与 Alt-Svc、quic_gso 与 0-RTT 的前置条件。","source":"https://daiw.org/manual/nginx/http2-http3"},"headers":[],"relativePath":"manual/tools/nginx/http2-http3.md","filePath":"manual/tools/nginx/http2-http3.md"}'),p={name:"manual/tools/nginx/http2-http3.md"};function r(l,s,i,o,c,d){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="http-2-与-http-3" tabindex="-1">HTTP/2 与 HTTP/3 <a class="header-anchor" href="#http-2-与-http-3" aria-label="Permalink to &quot;HTTP/2 与 HTTP/3&quot;">​</a></h1><p>协议本身的差异见<a href="https://daiw.org/manual/http2-3" target="_blank" rel="noreferrer">《HTTP/2 与 HTTP/3 协议详解》</a>，本章只讲怎么配。</p><h2 id="http-2" tabindex="-1">HTTP/2 <a class="header-anchor" href="#http-2" aria-label="Permalink to &quot;HTTP/2&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    http2 on | off;</span></span>
<span class="line"><span>默认:    http2 off;</span></span>
<span class="line"><span>上下文:  http, server</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    listen 443 ssl;</span></span>
<span class="line"><span>    http2  on;              # ← 新写法</span></span>
<span class="line"><span>    # listen 443 ssl http2; # ← 旧写法，已废弃</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><a href="/Front2Full/manual/tools/nginx/server-listen">前面提过</a>：<strong><code>listen ... http2</code> 参数已被官方标记为废弃</strong>（1.25.1 起分离出独立指令）。</p><p>两点差异：</p><ul><li>旧写法是<strong>端口级</strong>的：同端口上所有 server 一起开关。</li><li>新指令上下文是 <code>http, server</code>，可<strong>按 server 独立配置</strong>。</li></ul><p>旧写法目前仍工作，但新配置应该用 <code>http2 on;</code>。</p><p>浏览器只在 TLS 上用 HTTP/2（靠 ALPN 协商），所以实际上 <code>http2 on</code> 总是与 <code>listen ... ssl</code> 搭配。明文 h2c 浏览器不支持，<a href="https://daiw.org/manual/http2-3/h2-overview" target="_blank" rel="noreferrer">官方也已废弃 h2c 升级机制</a>。</p><h3 id="常用调优" tabindex="-1">常用调优 <a class="header-anchor" href="#常用调优" aria-label="Permalink to &quot;常用调优&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>http2_max_concurrent_streams</code></td><td>并发流上限，对应 <a href="https://daiw.org/manual/http2-3/h2-settings-priority" target="_blank" rel="noreferrer"><code>SETTINGS_MAX_CONCURRENT_STREAMS</code></a></td></tr><tr><td><code>http2_recv_buffer_size</code></td><td>接收缓冲</td></tr><tr><td><code>http2_chunk_size</code></td><td>响应体分块大小</td></tr></tbody></table><p><code>http2_max_concurrent_streams</code> 是防 <a href="https://daiw.org/manual/http2-3/h2-framing" target="_blank" rel="noreferrer">Rapid Reset（CVE-2023-44487）</a>一类流洪泛的关键——nginx 有默认值（128），但高危环境可调低。</p><p><strong><code>http2_push</code> 相关指令已随<a href="https://daiw.org/manual/http2-3/h2-server-push" target="_blank" rel="noreferrer">服务端推送废弃</a>而移除</strong>。浏览器已全面移除推送支持，配了也不生效。要优化关键资源加载请改用 <code>103 Early Hints</code> + <code>Link: rel=preload</code>。</p><p>另外，<strong>1.31.7 起 HTTP/2 优先级调度已切换为 <a href="https://daiw.org/manual/http2-3/h2-settings-priority" target="_blank" rel="noreferrer">RFC 9218 可扩展优先级方案</a></strong>：握手中默认发送 <code>SETTINGS_NO_RFC7540_PRIORITIES = 1</code>，忽略旧的 RFC 7540 依赖树帧，改按 <code>Priority</code> 请求头、<code>PRIORITY_UPDATE</code> 帧以及上游返回的 <code>Priority</code> 响应头合并调度。</p><h2 id="http-3-quic" tabindex="-1">HTTP/3 / QUIC <a class="header-anchor" href="#http-3-quic" aria-label="Permalink to &quot;HTTP/3 / QUIC&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    http3 on | off;</span></span>
<span class="line"><span>默认:    http3 on;            ← 注意默认是 on</span></span>
<span class="line"><span>上下文:  http, server</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>http3</code> 指令<strong>默认就是 on</strong>——但它只控制「协商时是否接受 HTTP/3」，真正让 QUIC 生效的是 <code>listen ... quic</code>。</p><h3 id="双-listen" tabindex="-1">双 listen <a class="header-anchor" href="#双-listen" aria-label="Permalink to &quot;双 listen&quot;">​</a></h3><p>官方给的标准配置：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    listen 8443 quic reuseport;   # UDP，QUIC</span></span>
<span class="line"><span>    listen 8443 ssl;              # TCP，HTTP/1.1 + HTTP/2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    http2 on;</span></span>
<span class="line"><span>    ssl_certificate     ...;</span></span>
<span class="line"><span>    ssl_certificate_key ...;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    add_header Alt-Svc &#39;h3=&quot;:8443&quot;; ma=86400&#39;;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>四个要点：</p><p><strong>一、必须两条 listen。</strong> QUIC 跑在 <strong>UDP</strong> 上，普通 HTTPS 跑 TCP——两个不同的套接字。同端口号但协议不同，不冲突。</p><p><strong>二、官方建议用同一个端口号。</strong> 注释原文是 <code>Use same port for HTTP/3 and HTTPS for better compatibility</code>——不同端口会让 <code>Alt-Svc</code> 通告变复杂，且部分网络环境下非 443 的 UDP 更容易被拦。</p><p><strong>三、<code>reuseport</code> 写在 quic 那条上</strong>，且同 address:port <a href="/Front2Full/manual/tools/nginx/server-listen">只能写一次</a>。</p><p><strong>四、必须发 <code>Alt-Svc</code>。</strong> 这是<a href="https://daiw.org/manual/http2-3/h3-connection" target="_blank" rel="noreferrer">服务发现</a>的唯一途径——客户端不会凭空知道你支持 h3。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_header Alt-Svc &#39;h3=&quot;:443&quot;; ma=86400&#39;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>ma</code> 是通告有效期（秒）。<strong>首次访问一定走 TCP</strong>，客户端记下通告后<strong>下次</strong>才尝试 QUIC。想消除这一跳需要配 <a href="https://daiw.org/manual/http2-3/h3-connection" target="_blank" rel="noreferrer">DNS HTTPS 记录</a>（RFC 9460），那是 DNS 侧的事，nginx 管不了。</p><p>别忘了 <code>add_header</code> 的<a href="/Front2Full/manual/tools/nginx/contexts">继承覆盖问题</a>——某个 location 里加了别的头，<code>Alt-Svc</code> 就没了，h3 也就不会被发现。</p><h3 id="tls-1-3-是硬前提" tabindex="-1">TLS 1.3 是硬前提 <a class="header-anchor" href="#tls-1-3-是硬前提" aria-label="Permalink to &quot;TLS 1.3 是硬前提&quot;">​</a></h3><p>QUIC <strong>内建 TLS 1.3</strong>，所以：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssl_protocols TLSv1.2 TLSv1.3;    # 默认值已包含 1.3，够用</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>若显式禁掉 TLS 1.3，QUIC 直接不可用。</p><h3 id="quic-gso" tabindex="-1">quic_gso <a class="header-anchor" href="#quic-gso" aria-label="Permalink to &quot;quic\\_gso&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    quic_gso on | off;</span></span>
<span class="line"><span>默认:    quic_gso off;</span></span>
<span class="line"><span>上下文:  http, server</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>启用 <strong>UDP 分段卸载</strong>（<code>UDP_SEGMENT</code>）批量发包，<strong>仅 Linux 且内核支持</strong>时有效。</p><p>这是针对 <a href="https://daiw.org/manual/http2-3/h3-overview" target="_blank" rel="noreferrer">HTTP/3 的 CPU 开销问题</a>的优化——UDP 路径的每包开销远高于 TCP，GSO 能把多个包合并成一次系统调用。高流量场景值得开，但<strong>要实测</strong>：内核/网卡不支持时可能反而出问题。</p><h3 id="quic-retry" tabindex="-1">quic_retry <a class="header-anchor" href="#quic-retry" aria-label="Permalink to &quot;quic\\_retry&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    quic_retry on | off;</span></span>
<span class="line"><span>默认:    quic_retry off;</span></span>
<span class="line"><span>上下文:  http, server</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>启用 QUIC <strong>地址验证</strong>（Retry 包 + token）。</p><p>作用是防 <strong>放大攻击</strong>——攻击者伪造源 IP 发小包，让服务器向受害者发大量数据。开启后服务器会先要求客户端证明自己确实在那个地址上，代价是多一个 RTT。</p><p>公网暴露的服务建议开启。</p><h3 id="_0-rtt-的前置条件" tabindex="-1">0-RTT 的前置条件 <a class="header-anchor" href="#_0-rtt-的前置条件" aria-label="Permalink to &quot;0-RTT 的前置条件&quot;">​</a></h3><p>官方特别注明：</p><blockquote><p>0-RTT support requires <strong>OpenSSL 3.5.1+</strong> or BoringSSL/LibreSSL/QuicTLS. Before NGINX 1.29.1, 0-RTT could not be enabled with OpenSSL regardless of the <code>ssl_early_data</code> directive value.</p></blockquote><p><strong>历史上用 OpenSSL 编译的 nginx，<code>ssl_early_data on;</code> 对 QUIC 完全无效</strong>——不报错，就是不生效。这个坑很隐蔽：配置看着对，抓包发现从来没有 0-RTT。</p><p>条件：nginx ≥ 1.29.1 <strong>且</strong> OpenSSL ≥ 3.5.1（或用 BoringSSL/QuicTLS 编译）。</p><p><code>nginx -V</code> 可以看编译时链接的 TLS 库。</p><p>即便可用，也请先读 <a href="/Front2Full/manual/tools/nginx/ssl">0-RTT 的重放风险</a>——默认关闭是有道理的。</p><h3 id="http3-hq" tabindex="-1">http3_hq <a class="header-anchor" href="#http3-hq" aria-label="Permalink to &quot;http3\\_hq&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    http3_hq on | off;</span></span>
<span class="line"><span>默认:    http3_hq off;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>HTTP/0.9-over-QUIC，<strong>仅用于 QUIC 互操作性测试</strong>。生产环境不要碰。</p><h2 id="完整配置" tabindex="-1">完整配置 <a class="header-anchor" href="#完整配置" aria-label="Permalink to &quot;完整配置&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    # TCP：HTTP/1.1 + HTTP/2</span></span>
<span class="line"><span>    listen 443 ssl;</span></span>
<span class="line"><span>    listen [::]:443 ssl;</span></span>
<span class="line"><span>    http2  on;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # UDP：HTTP/3</span></span>
<span class="line"><span>    listen 443 quic reuseport;</span></span>
<span class="line"><span>    listen [::]:443 quic;</span></span>
<span class="line"><span>    http3  on;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    server_name example.com;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ssl_certificate     /etc/ssl/fullchain.pem;</span></span>
<span class="line"><span>    ssl_certificate_key /etc/ssl/privkey.pem;</span></span>
<span class="line"><span>    ssl_protocols       TLSv1.2 TLSv1.3;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    quic_retry on;</span></span>
<span class="line"><span>    # quic_gso on;        # Linux 上实测后再开</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 必须：告诉客户端有 h3</span></span>
<span class="line"><span>    add_header Alt-Svc &#39;h3=&quot;:443&quot;; ma=86400&#39; always;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div><p><strong>防火墙记得放行 UDP 443</strong>——这是 h3 上不去最常见的原因，且现象是「静默回退到 TCP」，不报任何错。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curl -sI --http3 https://example.com | head -1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curl -sI --http2 https://example.com | head -1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>浏览器 DevTools 的 Network 面板加一列 Protocol，能看到 <code>h3</code> / <code>h2</code> / <code>http/1.1</code>。</p><p><strong>必须保留 HTTP/2 与 HTTP/1.1 回退。</strong> 部分企业网络与运营商限制 UDP，只开 h3 会让这些用户完全无法访问——详见<a href="https://daiw.org/manual/http2-3/migration-notes" target="_blank" rel="noreferrer">迁移注意事项</a>。上面的双 listen 配置天然满足这一点。</p><p>下一篇：<a href="/Front2Full/manual/tools/nginx/caching">缓存</a>。</p>`,61)])])}const b=a(p,[["render",r]]);export{u as __pageData,b as default};
